"""Action handlers. Each takes the Context first, then the action's declared inputs."""

from __future__ import annotations

from typing import Any

from alpha_sdk import Context


def add_book(ctx: Context, title: str) -> dict[str, Any]:
    """Add one book to the reading list, not finished yet."""
    clean = title.strip()
    if not clean:
        raise ValueError("A book needs a title.")
    record = ctx.records.create("books", {"title": clean, "finished": False})
    return {"id": record.id, "revision": record.revision}


def finish_book(ctx: Context, id: str) -> dict[str, Any]:
    """Mark one book as finished. Already finished books stay finished."""
    record = ctx.records.get("books", id)
    if record.get("finished"):
        return {"id": record.id, "revision": record.revision}
    updated = ctx.records.update(
        "books",
        record.id,
        expected_revision=record.revision,
        changes={"finished": True},
    )
    return {"id": updated.id, "revision": updated.revision}

