"""Supplementary tests for the reading list handlers, with a stand-in Context."""

from __future__ import annotations

import unittest

from app_code.handlers import add_book, finish_book


class FakeRecord:
    def __init__(self, record_id: str, revision: int, values: dict) -> None:
        self.id = record_id
        self.revision = revision
        self.values = dict(values)

    def get(self, name: str):
        return self.values.get(name)


class FakeRecords:
    def __init__(self) -> None:
        self.rows: dict[str, FakeRecord] = {}
        self.next_id = 1

    def create(self, collection: str, values: dict) -> FakeRecord:
        assert collection == "books"
        record_id = "book-%d" % self.next_id
        self.next_id += 1
        record = FakeRecord(record_id, 1, values)
        self.rows[record_id] = record
        return record

    def get(self, collection: str, record_id: str) -> FakeRecord:
        assert collection == "books"
        if record_id not in self.rows:
            raise KeyError(record_id)
        return self.rows[record_id]

    def update(self, collection: str, record_id: str, *, expected_revision: int, changes: dict):
        assert collection == "books"
        record = self.rows[record_id]
        if record.revision != expected_revision:
            raise AssertionError("stale revision")
        record.values.update(changes)
        record.revision += 1
        return record


class FakeContext:
    def __init__(self) -> None:
        self.records = FakeRecords()


class AddBookTests(unittest.TestCase):
    def test_stores_an_unfinished_book(self) -> None:
        ctx = FakeContext()
        out = add_book(ctx, title="The Left Hand of Darkness")
        stored = ctx.records.rows[out["id"]]
        self.assertEqual(stored.values, {"title": "The Left Hand of Darkness", "finished": False})
        self.assertEqual(out["revision"], stored.revision)

    def test_trims_surrounding_spaces(self) -> None:
        ctx = FakeContext()
        out = add_book(ctx, title="  Piranesi  ")
        self.assertEqual(ctx.records.rows[out["id"]].values["title"], "Piranesi")

    def test_refuses_a_blank_title(self) -> None:
        ctx = FakeContext()
        with self.assertRaises(ValueError):
            add_book(ctx, title="   ")
        self.assertEqual(ctx.records.rows, {})


class FinishBookTests(unittest.TestCase):
    def test_marks_the_book_finished(self) -> None:
        ctx = FakeContext()
        added = add_book(ctx, title="Piranesi")
        out = finish_book(ctx, id=added["id"])
        self.assertTrue(ctx.records.rows[added["id"]].values["finished"])
        self.assertEqual(out["id"], added["id"])

    def test_finishing_twice_is_harmless(self) -> None:
        ctx = FakeContext()
        added = add_book(ctx, title="Piranesi")
        finish_book(ctx, id=added["id"])
        out = finish_book(ctx, id=added["id"])
        self.assertTrue(ctx.records.rows[added["id"]].values["finished"])
        self.assertEqual(out["revision"], ctx.records.rows[added["id"]].revision)


if __name__ == "__main__":
    unittest.main()

