// Reading list: type a title to add a book, see every book newest first, mark one finished.
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "@alpha/ui-kit/styles.css";
import {
  AlphaApp,
  Badge,
  Button,
  OperationStatus,
  Page,
  QuickEntry,
  RecordTable,
  Section,
  useAction,
  useView,
  type RecordRow,
} from "@alpha/ui-kit";

type Book = { title: string; finished: boolean };

function App() {
  const add = useAction("add_book");
  const finish = useAction("finish_book");
  const books = useView<Book>("books.recent", { limit: 100 });

  return (
    <Page title="Reading list" description="Add a book by its title. The newest book is at the top.">
      <Section title="Add a book">
        <QuickEntry
          label="Title"
          parse={(text) => {
            const title = text.trim();
            return title ? { status: "ok", value: title, summary: title } : { status: "empty" };
          }}
          onSubmit={async (title) => {
            await add.run({ title });
          }}
        />
        <OperationStatus state={add.state} error={add.error} />
      </Section>

      <Section title="Books" description="Newest first.">
        <RecordTable<RecordRow<Book>>
          caption="Books on the reading list, newest first"
          columns={[
            { id: "title", header: "Title", cell: (row) => row.values.title },
            {
              id: "finished",
              header: "Finished",
              cell: (row) =>
                row.values.finished ? (
                  <Badge tone="success">Finished</Badge>
                ) : (
                  <Badge tone="info">Reading</Badge>
                ),
            },
            {
              id: "mark",
              header: "Mark finished",
              cell: (row) =>
                row.values.finished ? null : (
                  <Button
                    small
                    variant="secondary"
                    busy={finish.state === "saving"}
                    busyLabel="Saving…"
                    onClick={async () => {
                      try {
                        await finish.run({ id: row.id });
                      } catch {
                        /* OperationStatus below explains what went wrong. */
                      }
                    }}
                  >
                    Mark finished
                  </Button>
                ),
            },
          ]}
          rows={books.records}
          getRowId={(row) => row.id}
          getRowLabel={(row) => row.values.title}
          loading={books.loading}
          error={books.error}
          onRetry={books.refresh}
          empty={{ title: "No books yet", message: "Add your first book above." }}
        />
        <OperationStatus state={finish.state} error={finish.error} />
      </Section>
    </Page>
  );
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <AlphaApp>
      <App />
    </AlphaApp>
  </StrictMode>,
);
